entity Prob_8_12a_Counter_4bit_Synch_Clr_vhdl is		port (A: Std_Logic_vector (3 downto 0); output next_stage, Count_enable, Clear, CLK: in bit);end Prob_8_12_Counter_4bit_Synch_Clr_vhdl;architecture Structural of Prob_8_12_Counter_4bit_Synch_Clr_vhdl is  	signal A0, A1, A2, A3: Std_Logic;		component JK_FF port (Q: buffer bit; J, K, clock: in bit); end component;		component and2_gate port (y: out bit; xin1, xin2: in bit); end component;		component or2_gate port (y: out bit; xin1, xin2: in bit); end component;		component not_gate port (y: out bit; xin: in bit); end component;begin 	A(3 downto 0) <= A3 & A2 & A1 & A0;  	M0: JK_FF port map (A0, J0, K0, CLK); 	M1: JK_FF port map (A1, J1, K1, CLK); 	M2: JK_FF port map (A2, J2, K2, CLK);  			M3: JK_FF port map (A3, J3, K3, CLK);  	M4: not_gate port map (Clear_b, Clear);  	M6: and port map (J0, Count_enable, Clear_b);  	M7: and port map (J1, J0, A0);  	M8: and port map (J2, J1, A1);  	M9: and port map (J3, J2, A2);  	M10: or port map (K0, Clear, J0);  	M11: or port map (K1, Clear, J1);  	M12: or port map (K2, Clear, J2);  	M13: or port map (K3, Clear, J3);  	M14: and port map (next_stage, A3, J3);end Structural;entity JK_FF is		port (Q: buffer bit;   J, K, clock: in bit);end JK_FF;architecture Behavioral of JK_FF isbegin  process  (clock) begin		if 	clock'event and clock = '1' then    		case (J & K) is      			when "00":	Q <= Q;      			when "01":	Q <= 0;      			when "10":	Q <= 1;      			when "11":	Q <= not Q;    		end case;end Behavioral;entity and2_gate is  port (y: out bit; xin1, xin2: in bit);end and2_gate;architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;entity or2_gate is  port (y: out bit; xin1, xin2: in bit);end oro2_gate;architecture Behavioral of or2_gate isbegin	y <= xin1 and xin2;end Behavioral;entity not_gate is  port (y: out bit; xin: in bit);end not_gate;architecture Behavioral of not_gate isbegin	y <= not xin;end Behavioral;